  "Ohne Raten": "Ohne Raten",
  "Ojo del farol de tormenta": "Ojo del farol de tormenta",
  "Oleada": "Oleada",
  "Oleada {round}/{total}: ¡llegan nuevos enemigos!": "Oleada {round}/{total}: Alle neuen Feinde!",
  "Oleada {wave} asegurada": "Oleada {wave} asegurada",
