  "Stage list": "Bühnenliste",
  "Stage locked": "Bühne gesperrt",
  "Stage locked.": "Bühne gesperrt.",
  "Stage Map": "Bühnenkarte",
  "Stage modes": "Bühnenmodi",
  "Stage progress": "Bühnenfortschritt",
